/* Playable development proposal; all progress is reset when this review page reloads. */
const VentureDevelopmentUI=(()=>{
    const M=MageVentureDevelopment;let selected='mine',tab='production',serial=0;
    const data=()=>state.ventureDevelopment;
    const number=n=>Number(n.toFixed(1)).toLocaleString('en');
    const name=id=>id==='mine'?'Moonstone mine':'Silverfin pond';
    const siteArt=id=>'venture-site-'+id;
    const activityArt=id=>'venture-activity-'+(id==='mine'?'refinery':'sanctuary');
    const materialArt=id=>'venture-'+({glassEel:'glass-eel',starKoi:'star-koi'}[id]||id);
    const glyphMaterial=id=>{const r=M.find(id);return EncounterArt.markup(materialArt(id),'material-glyph '+r.venture);};
    const stock=(id,compact=false)=>`${glyphMaterial(id)}${compact?'':'<span>'+M.find(id).name+'</span>'}<b>${Math.floor(data().stock[id]).toLocaleString('en')}</b>`;
    const cost=items=>Object.entries(items).map(([id,n])=>{const r=M.find(id),owned=r?data().stock[id]:state[id],label=r?.name||({ore:'Ore',pearls:'Pearls'})[id];return `<span class="${owned<n?'is-short':''}" aria-label="${n} ${label}${owned<n?', not enough':''}" title="${n} ${label}">${r?glyphMaterial(id):ui(id,'inline-icon')}<b>${n}</b></span>`;}).join('');
    const command=(action,target,label,q,extra='')=>`<button class="rune-button ${extra}" data-v-command="${action}" data-v-target="${target}" aria-label="${action==='refine'?'Refine '+M.recipes.find(r=>r.id===target).name:action==='stock'?'Shelter 5 '+M.find(target).name:label}" ${q.ok?'':'disabled'}>${label}</button>`;
    function workers(id){const all=state.ventureSpirits.owned.filter(s=>s.assigned===id),base=id==='mine'?state.mining:state.fishing;return `<button class="venture-crew" data-spirit-list="${id}" aria-label="Manage ${all.length} loot spirits assigned to ${name(id)}. ${base} base spirits always working">${sprite('spirit')}<span><strong>Spirits</strong><small>${base} base · ${all.length} loot</small></span><b aria-hidden="true">›</b></button>`;}
    function overview(){const d=data(),rates=M.production(d,MageVentureSpirits.production(state,state.ventureSpirits));return `<section class="page ventures-page spirit-ventures venture-development venture-polish"><div class="compact-heading">${title('Ventures')}<button class="text-button" data-view="spirits">${sprite('spirit')} Spirits ›</button></div>${['mine','pond'].map(id=>{const v=d[id],r=M.find(v.selected);return `<section class="venture-card site-${id}"><button class="venture-open" data-v-open="${id}" aria-label="Develop ${name(id)}"><span class="venture-site-art">${sprite(siteArt(id))}</span><span class="venture-card-copy"><small class="venture-stage">${id==='mine'?'DEPTH':'HABITAT'} ${v.level} / 4<span class="venture-stage-pips" aria-hidden="true">${[1,2,3,4].map(n=>`<i class="${n<=v.level?'reached':''}"></i>`).join('')}</span></small><strong>${name(id)}</strong><span class="venture-current">${glyphMaterial(r.id)}<span>${r.name}</span><b>${number(rates[r.id])}<small>/min</small></b></span></span><b class="venture-chevron" aria-hidden="true">›</b></button><div class="venture-card-actions"><button class="venture-activity-link" data-v-open="${id}" data-v-open-tab="craft">${sprite(activityArt(id))}<span>${id==='mine'?'Refinery':'Sanctuary'}</span><b aria-hidden="true">›</b></button>${workers(id)}</div></section>`;}).join('')}</section>`;}
    function expand(id){const v=data()[id],q=M.quote(state,'upgrade',id),next=M.find(q.next);return `<section class="venture-expansion ${next?'':'fully-expanded'}">${next?glyphMaterial(next.id):ui('crest')}<div><small>${next?'NEXT '+(id==='mine'?'DEPTH':'HABITAT'):'COMPLETE'}${next?' · +1 spirit':''}</small><strong>${next?next.name:'Fully expanded'}</strong>${next?`<div class="venture-cost">${cost(q.cost)}</div>`:'<span class="venture-purpose">Every resource available</span>'}</div>${next?command('upgrade',id,'Expand',q):'<b class="expansion-complete" aria-label="All resources unlocked">✓</b>'}</section>`;}
    function production(id){const d=data(),v=d[id],rates=MageVentureSpirits.production(state,state.ventureSpirits),materials=M.production(d,rates),r=M.find(v.selected),base=id==='mine'?'ore':'pearls';return `<div class="venture-output">${glyphMaterial(r.id)}<div class="venture-output-copy"><strong>${r.name}</strong><small><b>${Math.floor(d.stock[r.id])}</b> stored <span class="base-output" aria-label="${number(rates[base])} ${base} per minute">${ui(base,'inline-icon')}${number(rates[base])}/min</span></small></div><button class="venture-production-info" data-action="${id==='mine'?'mineInfo':'pondInfo'}" aria-label="Production and bonuses for ${name(id)}: ${number(materials[r.id])} ${r.name} per minute"><b>${number(materials[r.id])}<small>/min</small></b><span>Details ${glyph('info')}</span></button></div><div class="venture-resource-grid" role="group" aria-label="Choose ${id==='mine'?'vein':'fishing habitat'}">${M.resources.filter(r=>r.venture===id).map(r=>{const unlocked=r.level<=v.level;return `<button data-v-command="select" data-v-target="${r.id}" aria-label="${r.name}, ${unlocked?Math.floor(d.stock[r.id])+' stored. Select production':(id==='mine'?'Depth ':'Habitat ')+r.level+' required'}" aria-pressed="${v.selected===r.id}" ${unlocked?'':'disabled'}>${glyphMaterial(r.id)}<strong>${r.name}</strong><small>${unlocked?Math.floor(d.stock[r.id]):(id==='mine'?'Depth ':'Habitat ')+r.level}</small>${v.selected===r.id?'<i class="selected-resource" aria-hidden="true">◆</i>':''}</button>`;}).join('')}</div>${expand(id)}`;}
    function upgrades(id){const mine=id==='mine',base=mine?'ore':'pearls',amount=mine?40:30;return `<div class="venture-upgrades"><div class="venture-upgrade-heading"><strong>Permanent stats</strong></div><button class="rune-button venture-stat-upgrade" data-action="${mine?'buyDamage':'buyHp'}" ${state[base]<amount?'disabled':''} aria-label="Buy permanent ${mine?'+5 Spell power for 40 Ore':'+10 HP for 30 Pearls'}"><span>${ui(mine?'power':'hp')}<b>+${mine?5:10}</b><small>${mine?'Spell power':'HP'}</small></span><span class="upgrade-cost">${ui(base)}${amount}</span></button>${!mine?`<section class="venture-cross-upgrade"><div>${sprite('venture-site-mine')}<span><strong>Moonstone synergy</strong><small>Mine production ×1.25</small></span></div>${state.synergy?'<span class="synergy-active">✓ Active</span>':`<button class="rune-button secondary cross-synergy-action" data-action="synergy" aria-label="Activate mine production ×1.25 for50 Pearls" ${state.pearls<50?'disabled':''}><span>Activate</span><span>${ui('pearls')}50</span></button>`}</section>`:''}${workers(id)}</div>`;}
    function refinery(){const d=data();return `<div class="venture-stock-strip" aria-label="Metals available">${M.resources.filter(r=>r.venture==='mine').map(r=>`<span title="${r.name}" aria-label="${r.name}: ${Math.floor(d.stock[r.id])}">${stock(r.id,true)}</span>`).join('')}</div><div class="venture-recipes">${M.recipes.map(r=>{const q=M.quote(state,'refine',r.id),locked=d.mine.level<r.level;return `<section class="venture-recipe ${locked?'locked':''}"><div class="recipe-copy"><div class="recipe-title"><strong>${r.name}</strong><small>${locked?'Depth '+r.level:'×'+d.refined[r.id]}</small></div><div class="venture-cost">${cost(locked?r.cost:q.cost)}</div></div>${command('refine',r.id,ui('power','inline-icon')+' <b>+'+r.power+'</b>',q)}</section>`;}).join('')}</div><div class="refinery-caption">${ui('power')} Permanent Spell power</div>`;}
    function sanctuary(){const d=data(),b=M.bonuses(d);return `<div class="sanctuary-summary">${sprite('venture-activity-sanctuary')}<span><strong>${d.sanctuary.length} / 4 sheltered</strong><small>${sprite('venture-site-mine')} ×${number(b.mine)} <span>All 4: ${ui('pearls')} ×1.25</span></small></span><div class="sanctuary-pips" aria-label="${d.sanctuary.length} of four species sheltered">${[0,1,2,3].map(n=>`<i class="${n<d.sanctuary.length?'sheltered':''}"></i>`).join('')}</div></div><div class="sanctuary-grid">${M.resources.filter(r=>r.venture==='pond').map(r=>{const q=M.quote(state,'stock',r.id),done=d.sanctuary.includes(r.id),locked=r.level>d.pond.level;return `<section class="sanctuary-species ${done?'sheltered':''} ${locked?'locked':''}"><div class="species-title">${glyphMaterial(r.id)}<span><strong>${r.name}</strong><small>${done?'Mine +5%':locked?'Habitat '+r.level:Math.floor(d.stock[r.id])+' / 5'}</small></span></div>${command('stock',r.id,done?'✓ Sheltered':locked?'Locked':'Shelter 5',q,done||!q.ok?'secondary':'')}</section>`;}).join('')}</div>`;}
    function detail(){const level=data()[selected].level;return `<section class="page venture-detail-page venture-development venture-polish site-${selected}"><div class="venture-detail-heading"><button class="venture-back" data-view="ventures" aria-label="Back to Ventures">‹</button>${sprite(siteArt(selected))}<div><h2>${name(selected)}</h2><small>${selected==='mine'?'Depth':'Habitat'} ${level} / 4</small></div></div><nav class="venture-tabs" aria-label="Venture activity"><button data-v-tab="production" aria-pressed="${tab==='production'}">${glyphMaterial(data()[selected].selected)}<span>${selected==='mine'?'Veins':'Habitats'}</span></button><button data-v-tab="craft" aria-pressed="${tab==='craft'}">${sprite(activityArt(selected))}<span>${selected==='mine'?'Refinery':'Sanctuary'}</span></button><button data-v-tab="upgrades" aria-pressed="${tab==='upgrades'}">${ui('power')}<span>Upgrades</span></button></nav>${tab==='production'?production(selected):tab==='upgrades'?upgrades(selected):selected==='mine'?refinery():sanctuary()}</section>`;}
    function open(id,section='production'){selected=id;tab=section;go('ventureDetail');}
    function restoreFocus(selector){const node=phone.querySelector(selector);(node&&!node.disabled?node:phone.querySelector('[data-v-tab="'+tab+'"]'))?.focus({preventScroll:true});}
    function handle(el){if(el.dataset.vOpen){open(el.dataset.vOpen,el.dataset.vOpenTab||'production');return true;}if(el.dataset.vTab){tab=el.dataset.vTab;render(true);restoreFocus('[data-v-tab="'+tab+'"]');return true;}if(state.view==='ventureDetail'&&['buyDamage','buyHp','synergy'].includes(el.dataset.action)){const action=el.dataset.action;actions[action]();restoreFocus('[data-action="'+action+'"]');return true;}if(el.dataset.vCommand){const action=el.dataset.vCommand,target=el.dataset.vTarget,q=M.quote(state,action,target),out=M.commit(state,{id:'venture-'+(++serial),action,target,token:q.token});if(out.ok){if(action==='select')render(true);else notify(action==='upgrade'?'Unlocked '+M.find(out.receipt.next).name:action==='refine'?'Permanent Spell power +'+out.receipt.power:'Species sheltered · Mine +5%');}else notify(out.reason||'Unable to complete action');restoreFocus('[data-v-command="'+action+'"][data-v-target="'+target+'"]');return true;}return false;}
    function seed(advanced=false){state.ventureDevelopment=M.fresh();Object.assign(data().stock,{tin:24,reedfin:16});if(advanced){for(const id of ['mine','pond'])data()[id].level=3;data().mine.selected='gold';data().pond.selected='glassEel';for(const r of M.resources.filter(r=>r.level<=3))data().stock[r.id]=40;state.ore=600;state.pearls=300;state.mining=4;state.fishing=3;}go('ventures');}
    function materialSummary(materials){return materials?`<span class="return-venture-materials">${Object.entries(materials).map(([id,n])=>`<span>${glyphMaterial(id)}<strong>+${Math.floor(n).toLocaleString('en')}</strong> ${M.find(id).name}</span>`).join('')}</span>`:'';}
    function balances(){return `<div class="venture-stock-strip resources-materials">${M.resources.filter(r=>data()[r.venture].level>=r.level).map(r=>`<span>${stock(r.id)}</span>`).join('')}</div>`;}
    function refresh(){const active=document.activeElement,attributes=[...(active?.attributes||[])].filter(a=>a.name.startsWith('data-')).map(a=>'['+a.name+'="'+CSS.escape(a.value)+'"]').join('');render(true);if(attributes)phone.querySelector('button'+attributes)?.focus({preventScroll:true});}
    return {overview,detail,handle,seed,refresh,open,returnMaterials:()=>materialSummary(state.returned?.materials),materialSummary,balances};
})();
